  KEY `idx_paciente_documento` (`PACIENTE_DOCUMENTO`),
  KEY `idx_cama_codigo` (`CAMA_CODIGO`),
  KEY `idx_entidad_codigo` (`INGRESO_ENTIDAD_CODIGO`),
  KEY `idx_ingreso_fecha` (`INGRESO_FECHA`)
) ENGINE=InnoDB AUTO_INCREMENT=168 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Registro de ocupación de camas por paciente/ingreso hospitalario';
